/* Parametric SVG drawings. No images, mesh downloads, or rendering dependencies.
 * The catenoid on the homepage remains in index.html. Costa is generated by
 * scripts/generate_costa.py. The helicoid is reserved for future Miscellanea.
 */
(() => {
  'use strict';
  const tau = 2 * Math.PI;
  const ns = 'http://www.w3.org/2000/svg';
  const labels = {
    torus: {
      pt: ['Toro', 'Toro de revolução representado por curvas coordenadas.'],
      en: ['Torus', 'A torus of revolution represented by coordinate curves.']
    },
    sphere: {
      pt: ['Esfera com geodésicas', 'Esfera unitária com grandes círculos, que são geodésicas da métrica redonda.'],
      en: ['Sphere with geodesics', 'A unit sphere with great circles, which are geodesics of the round metric.']
    },
    helicoid: {
      pt: ['Helicoide', 'Trecho de um helicoide mínimo representado por curvas coordenadas.'],
      en: ['Helicoid', 'A finite portion of a minimal helicoid represented by coordinate curves.']
    }
  };

  function project([x, y, z], yaw = .65, tilt = .62) {
    const horizontal = x * Math.cos(yaw) - y * Math.sin(yaw);
    const depth = x * Math.sin(yaw) + y * Math.cos(yaw);
    return [horizontal, depth * Math.sin(tilt) - z * Math.cos(tilt), depth * Math.cos(tilt) + z * Math.sin(tilt)];
  }

  function sample(fn, start = 0, end = tau, count = 160) {
    return Array.from({length: count + 1}, (_, i) => fn(start + (end - start) * i / count));
  }

  function torus() {
    const R = 1.65, r = .64;
    // X(u,v) = ((R+r cos v) cos u, (R+r cos v) sin u, r sin v).
    const point = (u, v) => project([(R + r * Math.cos(v)) * Math.cos(u), (R + r * Math.cos(v)) * Math.sin(u), r * Math.sin(v)]);
    const paths = [];
    for (let k = 0; k < 16; k++) {
      const v = tau * k / 16;
      paths.push({points: sample(u => point(u, v)), emphasis: k === 0 || k === 8});
    }
    for (let k = 0; k < 28; k++) {
      const u = tau * k / 28;
      paths.push({points: sample(v => point(u, v))});
    }
    return paths;
  }

  function sphere() {
    const paths = [];
    // Each curve is cos(t) a + sin(t) b for orthonormal a,b in R^3.
    // Every curve therefore lies in a plane through the origin: no latitude
    // circles are mislabeled as geodesics.
    const greatCircle = (a, b) => sample(t => project(a.map((value, i) => value * Math.cos(t) + b[i] * Math.sin(t)), .37, .44));
    const appendHalves = points => {
      let half = [points[0]], front = points[0][2] >= 0;
      for (let i = 1; i < points.length; i++) {
        const nextFront = points[i][2] >= 0;
        if (nextFront !== front) {
          const previous = points[i - 1], next = points[i];
          const t = previous[2] / (previous[2] - next[2]);
          const crossing = previous.map((value, j) => value + t * (next[j] - value));
          half.push(crossing);
          paths.push({points: half, opacity: front ? .64 : .18});
          half = [crossing];
          front = nextFront;
        }
        half.push(points[i]);
      }
      if (half.length > 1) paths.push({points: half, opacity: front ? .64 : .18});
    };
    for (let k = 0; k < 8; k++) {
      const angle = Math.PI * k / 8;
      appendHalves(greatCircle([Math.cos(angle), Math.sin(angle), 0], [0, 0, 1]));
    }
    appendHalves(greatCircle([1, 0, 0], [0, 1, 0]));
    for (const angle of [-Math.PI / 4, Math.PI / 4]) {
      appendHalves(greatCircle([1, 0, 0], [0, Math.cos(angle), Math.sin(angle)]));
    }
    // The apparent contour is itself a great circle in the viewing plane.
    paths.push({points: sample(t => [Math.cos(t), Math.sin(t), 0]), emphasis: true, opacity: .8});
    return paths;
  }

  function helicoid() {
    const paths = [], extent = 1.8, turns = 1.65 * Math.PI, pitch = .48;
    // X(u,v) = (v cos u, v sin u, pitch*u).
    const point = (u, v) => project([v * Math.cos(u), v * Math.sin(u), pitch * u], .4, .4);
    for (let k = 0; k <= 18; k++) {
      const v = -extent + 2 * extent * k / 18;
      paths.push({points: sample(u => point(u, v), -turns, turns), emphasis: k === 0 || k === 9 || k === 18});
    }
    for (let k = 0; k <= 34; k++) {
      const u = -turns + 2 * turns * k / 34;
      paths.push({points: sample(v => point(u, v), -extent, extent, 40)});
    }
    return paths;
  }

  function draw(svg, kind, language = 'pt') {
    const generator = {torus, sphere, helicoid}[kind];
    if (!generator) return;
    const paths = generator(), width = 420, height = 280;
    const all = paths.flatMap(path => path.points);
    const minX = Math.min(...all.map(p => p[0])), maxX = Math.max(...all.map(p => p[0]));
    const minY = Math.min(...all.map(p => p[1])), maxY = Math.max(...all.map(p => p[1]));
    const scale = Math.min((width - 28) / (maxX - minX), (height - 24) / (maxY - minY));
    const cx = (maxX + minX) / 2, cy = (maxY + minY) / 2;
    const [name, description] = labels[kind][language === 'en' ? 'en' : 'pt'];
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', name);
    const title = document.createElementNS(ns, 'title');title.textContent = name;
    const desc = document.createElementNS(ns, 'desc');desc.textContent = description;
    const elements = [title, desc];
    paths.forEach(path => {path.depth = path.points.reduce((sum, p) => sum + p[2], 0) / path.points.length;});
    paths.sort((a, b) => a.depth - b.depth);
    for (const data of paths) {
      const path = document.createElementNS(ns, 'path');
      path.setAttribute('d', data.points.map((p, i) => `${i ? 'L' : 'M'}${(width / 2 + (p[0] - cx) * scale).toFixed(2)},${(height / 2 + (p[1] - cy) * scale).toFixed(2)}`).join(''));
      path.setAttribute('fill', 'none');
      path.setAttribute('stroke', 'currentColor');
      path.setAttribute('stroke-width', data.emphasis ? '1.05' : '.65');
      path.setAttribute('stroke-linecap', 'round');
      path.setAttribute('stroke-linejoin', 'round');
      path.setAttribute('vector-effect', 'non-scaling-stroke');
      path.setAttribute('opacity', String(data.opacity ?? (data.emphasis ? .85 : data.depth > 0 ? .6 : .25)));
      elements.push(path);
    }
    svg.replaceChildren(...elements);
  }

  window.BogoSurfaces = Object.freeze({draw});
})();
